}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String binary = "";
        long p = 1L << 30;
        while (p > 0 && (n & p) == 0) {
            p >>= 1;
        }
        if (n == 0) {
            binary = "0";
        }
        while (p > 0) {
            binary += ((n & p) != 0) ? "1" : "0";
            p >>= 1;
        }
        System.out.println("Binary: " + binary);
        System.out.println("Doubled: " + (n << 1));
        System.out.println("Halved: " + (n >> 1));
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        long m = sc.nextLong();
        long result = 1 % m;
        long base = a % m;
        while(b > 0) {
            if ((b & 1) == 1) {
                result = result * base % m;
            }
            base = base * base % m;
            b >>= 1;
        }
        System.out.println(result);
    }
}
